p {
  font-family: 'Arial', sans-serif;
  font-size: 16px;
  line-height: 1.5;
  letter-spacing: 0.5px;
  word-spacing: 2px;
  text-align: justify;
  text-transform: capitalize;
  font-weight: 500;
}

div {
  background-color: #f0f0f0;
  background-image: linear-gradient(to right, red, yellow);
  background-size: cover;
  background-position: center;
  background-repeat: no-repeat;
}

button:hover {
  background-color: blue;
  color: white;
}

p::before {
  content: "★ ";
  color: gold;
}

li:nth-child(odd) {
  background-color: #f0f0f0;
}

p {
  color: blue; /* inherited by default */
}

.text {
  color: green; /* class selector */
}

#mainText {
  color: red; /* ID selector has higher specificity */
}

<p id="mainText" class="text">Hello World</p>
<!-- This text will be red because ID selector wins -->

/* Absolute unit */
div { width: 200px; }

/* Relative units */
p { font-size: 1.2em; }  /* 1.2 times parent font size */
h1 { font-size: 2rem; }  /* 2 times root font size */
.container { width: 80%; }  /* 80% of parent width */
section { height: 50vh; }  /* 50% of viewport height */

/* Display */
div { display: block; }
span { display: inline; }
button { display: inline-block; }
.hidden-element { display: none; }

/* Visibility */
p.invisible { visibility: hidden; }

/* Overflow */
.container { width: 200px; height: 50px; overflow: auto; }

/* Text Overflow */
p.ellipsis {
  width: 150px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* Mobile-first styles */
body {
  font-size: 14px;
}

/* Tablet and above */
@media (min-width: 768px) {
  body {
    font-size: 16px;
  }
}

/* Desktop and above */
@media (min-width: 1024px) {
  body {
    font-size: 18px;
  }
}

/* Transition Example */
button {
  background-color: blue;
  transition: background-color 0.3s ease, transform 0.3s ease;
}

button:hover {
  background-color: darkblue;
  transform: scale(1.1);
}

/* Animation Example */
@keyframes fadeIn {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.card {
  animation: fadeIn 0.6s ease-in-out;
}
